[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "kitchen-renovation-schedule",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "kitchen-renovation-schedule",
      "value": {
        "scheduleItems": [
          {
            "phase": "Demolition",
            "startDate": "2024-05-01",
            "endDate": "2024-05-02",
            "duration": "2"
          },
          {
            "phase": "Electrical and Plumbing",
            "startDate": "2024-05-03",
            "endDate": "2024-05-05",
            "duration": "3"
          },
          {
            "phase": "Cabinet Installation",
            "startDate": "2024-05-06",
            "endDate": "2024-05-08",
            "duration": "3"
          },
          {
            "phase": "Countertop Templating/Install",
            "startDate": "2024-05-09",
            "endDate": "2024-05-10",
            "duration": "2"
          },
          {
            "phase": "Flooring",
            "startDate": "2024-05-11",
            "endDate": "2024-05-13",
            "duration": "3"
          },
          {
            "phase": "Backsplash and Painting",
            "startDate": "2024-05-14",
            "endDate": "2024-05-15",
            "duration": "2"
          }
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "kitchen-renovation-schedule",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium"
          },
          "children": [
            "title",
            "subtitle",
            "assumptions_card",
            "schedule_card",
            "actions_title",
            "actions_row"
          ]
        },
        {
          "id": "title",
          "type": "Text",
          "properties": {
            "text": "Kitchen Renovation Schedule",
            "style": "title"
          }
        },
        {
          "id": "subtitle",
          "type": "Text",
          "properties": {
            "text": "Here is a detailed schedule for your kitchen remodel from May 1, 2024, to May 15, 2024:"
          }
        },
        {
          "id": "assumptions_card",
          "type": "Card",
          "children": [
            "assumptions_list"
          ]
        },
        {
          "id": "assumptions_list",
          "type": "List",
          "properties": {
            "title": "Assumptions"
          },
          "children": [
            "assumption_1",
            "assumption_2"
          ]
        },
        {
          "id": "assumption_1",
          "type": "Text",
          "properties": {
            "text": "The renovation schedule starts precisely on 2024-05-01 and ends on 2024-05-15."
          }
        },
        {
          "id": "assumption_2",
          "type": "Text",
          "properties": {
            "text": "Each phase starts immediately after the previous one, with no buffer days."
          }
        },
        {
          "id": "schedule_card",
          "type": "Card",
          "children": [
            "schedule_column"
          ]
        },
        {
          "id": "schedule_column",
          "type": "Column",
          "properties": {
            "spacing": "small"
          },
          "children": [
            "header_row",
            "divider",
            "schedule_list"
          ]
        },
        {
          "id": "header_row",
          "type": "Row",
          "children": [
            "header_phase",
            "header_start",
            "header_end",
            "header_duration"
          ]
        },
        {
          "id": "header_phase",
          "type": "Text",
          "properties": {
            "text": "Phase",
            "weight": 3,
            "isBold": true
          }
        },
        {
          "id": "header_start",
          "type": "Text",
          "properties": {
            "text": "Start Date",
            "weight": 2,
            "isBold": true
          }
        },
        {
          "id": "header_end",
          "type": "Text",
          "properties": {
            "text": "End Date",
            "weight": 2,
            "isBold": true
          }
        },
        {
          "id": "header_duration",
          "type": "Text",
          "properties": {
            "text": "Duration",
            "weight": 1,
            "isBold": true,
            "horizontalAlignment": "end"
          }
        },
        {
          "id": "divider",
          "type": "Divider"
        },
        {
          "id": "schedule_list",
          "type": "List",
          "properties": {
            "childrenBinding": "dataModel.scheduleItems"
          },
          "childTemplate": {
            "id": "schedule_row_template",
            "type": "Row",
            "children": [
              {
                "id": "phase_text",
                "type": "Text",
                "properties": {
                  "text": "{{ phase }}",
                  "weight": 3
                }
              },
              {
                "id": "start_date_text",
                "type": "Text",
                "properties": {
                  "text": "{{ startDate }}",
                  "weight": 2
                }
              },
              {
                "id": "end_date_text",
                "type": "Text",
                "properties": {
                  "text": "{{ endDate }}",
                  "weight": 2
                }
              },
              {
                "id": "duration_text",
                "type": "Text",
                "properties": {
                  "text": "{{ duration }} Days",
                  "weight": 1,
                  "horizontalAlignment": "end"
                }
              }
            ]
          }
        },
        {
          "id": "actions_title",
          "type": "Text",
          "properties": {
            "text": "Quick Actions",
            "style": "subheading"
          }
        },
        {
          "id": "actions_row",
          "type": "Row",
          "properties": {
            "distribution": "spaceEvenly",
            "spacing": "medium"
          },
          "children": [
            "budget_button",
            "contractors_button",
            "designs_button"
          ]
        },
        {
          "id": "budget_button",
          "type": "Button",
          "properties": {
            "label": "Plan Your Renovation Budget",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "arguments": {
                "url": "https://example.com/budget-planner"
              }
            }
          }
        },
        {
          "id": "contractors_button",
          "type": "Button",
          "properties": {
            "label": "Find Local Kitchen Contractors",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "arguments": {
                "url": "https://example.com/find-contractors"
              }
            }
          }
        },
        {
          "id": "designs_button",
          "type": "Button",
          "properties": {
            "label": "Browse Kitchen Design Ideas",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "arguments": {
                "url": "https://example.com/kitchen-designs"
              }
            }
          }
        }
      ]
    }
  }
]
